-- NEXOVAX: legal texts aligned with the three seller trust levels (2026-11-27).
-- Run AFTER 20261127190000_nexovax_policy_alignment.sql and 20261127200000_nexovax_seller_trust_levels.sql.
--
-- The «Tienda verificada» badge (review of declared tax details) is gone. Stores now show only:
--   «Vendedor registrado» (no check), «Cobro verificado» (payout account verified by Finance) and
--   «Identidad verificada» (staff checked an official ID document or business registry).
-- Also corrects «every store declares its tax ID»: tax details are optional since 2026-11-25.
--
-- For BUYER_PROTECTION, ABOUT_US and SELLER_TERMS, one paragraph per language is replaced in the CURRENT
-- published version and a new version is published (no re-acceptance: no new obligation for anyone).
-- Idempotent: a policy is skipped when none of its paragraphs is found (already updated, or edited by hand
-- in Admin → Ajustes → Políticas legales — then edit that paragraph there).

do $$
declare
  c text; v_policy uuid; v_cur uuid; v_version uuid; v_next int; v_admin uuid; v_changed boolean; r record;
begin
  select ur.user_id into v_admin from public.user_roles ur join public.roles ro on ro.id = ur.role_id join public.users u on u.id = ur.user_id
   where ro.code = 'SUPER_ADMIN' and ur.revoked_at is null and u.status = 'ACTIVE' order by u.created_at limit 1;

  create temp table nx_trust_repl (code text, locale text, old_text text, new_text text) on commit drop;
  insert into nx_trust_repl values
    ('BUYER_PROTECTION', 'es', $t$Tiendas identificadas y verificadas: al registrarse, cada tienda declara su nombre o razón social, el tipo de entidad, su país, su identificación fiscal, su dirección y su teléfono, y puede empezar a vender desde ese momento. Verificamos manualmente su cuenta de cobro antes de pagarle. La insignia «Tienda verificada» aparece cuando nuestro equipo ha revisado los datos fiscales que la tienda declaró; no revisamos documentos de identidad.$t$, $t$Tiendas registradas y niveles de verificación: al registrarse, cada tienda declara el nombre de la tienda y sus datos de contacto y de despacho (los datos fiscales son opcionales), y puede empezar a vender desde ese momento, sin que revisemos documentos de identidad. Cada tienda muestra solo las insignias que corresponden a lo que hemos comprobado: «Vendedor registrado» (la tienda se registró; no implica ninguna verificación), «Cobro verificado» (verificamos manualmente la cuenta donde recibe sus pagos; nunca le pagamos a una cuenta sin verificar) e «Identidad verificada» (nuestro equipo comprobó su identidad con un documento oficial de identidad o un registro oficial de empresas). Revisar los datos que la tienda escribió no basta para esta última.$t$),
    ('BUYER_PROTECTION', 'en', $t$Identified and verified stores: when signing up, every store declares its name or legal name, entity type, country, tax ID, address and phone, and can start selling right away. We manually verify its payout account before paying it. The “Verified store” badge appears once our team has reviewed the tax details the store declared; we don’t check identity documents.$t$, $t$Registered stores and verification levels: when signing up, every store declares its store name and its contact and shipping details (tax details are optional), and can start selling right away, without us checking identity documents. Each store shows only the badges that match what we checked: “Registered seller” (the store signed up; no verification implied), “Payout verified” (we manually verified the account where it receives its payouts; we never pay an unverified account) and “Identity verified” (our team checked its identity with an official ID document or an official business registry). Reviewing the details the store typed is not enough for the latter.$t$),
    ('BUYER_PROTECTION', 'fr', $t$Boutiques identifiées et vérifiées : à l’inscription, chaque boutique déclare son nom ou sa raison sociale, son type d’entité, son pays, son identifiant fiscal, son adresse et son téléphone, et peut vendre immédiatement. Nous vérifions manuellement son compte de versement avant de la payer. Le badge « Boutique vérifiée » apparaît lorsque notre équipe a examiné les informations fiscales déclarées par la boutique ; nous ne contrôlons pas de pièces d’identité.$t$, $t$Boutiques enregistrées et niveaux de vérification : à l’inscription, chaque boutique déclare son nom de boutique et ses coordonnées de contact et d’expédition (les informations fiscales sont facultatives), et peut vendre immédiatement, sans que nous contrôlions de pièces d’identité. Chaque boutique n’affiche que les badges correspondant à ce que nous avons vérifié : « Vendeur enregistré » (la boutique s’est inscrite ; aucune vérification implicite), « Versement vérifié » (nous avons vérifié manuellement le compte sur lequel elle reçoit ses versements ; nous ne payons jamais un compte non vérifié) et « Identité vérifiée » (notre équipe a vérifié son identité avec une pièce d’identité officielle ou un registre officiel des entreprises). Examiner les informations saisies par la boutique ne suffit pas pour ce dernier.$t$),
    ('BUYER_PROTECTION', 'ht', $t$Boutik idantifye ak verifye: lè yon boutik enskri, li deklare non l oswa non legal li, kalite antite a, peyi l, idantifyan fiskal li, adrès li ak telefòn li, epi li ka kòmanse vann touswit. Nou verifye kont peman l alamen anvan nou peye l. Badj « Boutik verifye » parèt lè ekip nou an fin revize enfòmasyon fiskal boutik la te deklare yo; nou pa verifye dokiman idantite.$t$, $t$Boutik ki anrejistre ak nivo verifikasyon: lè yon boutik enskri, li deklare non boutik la ak enfòmasyon kontak ak ekspedisyon li (enfòmasyon fiskal yo opsyonèl), epi li ka kòmanse vann touswit, san nou pa verifye dokiman idantite. Chak boutik montre sèlman badj ki koresponn ak sa nou verifye: « Vandè ki anrejistre » (boutik la enskri; sa pa vle di okenn verifikasyon), « Peman verifye » (nou verifye alamen kont kote l resevwa peman l; nou pa janm peye yon kont ki pa verifye) ak « Idantite verifye » (ekip nou an verifye idantite l ak yon dokiman idantite ofisyèl oswa yon rejis ofisyèl antrepriz). Revize enfòmasyon boutik la ekri pa ase pou dènye a.$t$),
    ('ABOUT_US', 'es', $t$Tiendas: cada tienda se registra con su país, su identificación fiscal y la dirección desde donde despacha, y puede vender desde ese momento. Verificamos su cuenta de cobro antes de pagarle, y la insignia «Tienda verificada» indica que nuestro equipo revisó sus datos fiscales. Las reseñas de los compradores son públicas.$t$, $t$Tiendas: cada tienda se registra con la dirección desde donde despacha y puede vender desde ese momento. Verificamos su cuenta de cobro antes de pagarle. Sus insignias indican solo lo que comprobamos: «Vendedor registrado», «Cobro verificado» e «Identidad verificada» (identidad comprobada con un documento oficial o un registro oficial de empresas). Las reseñas de los compradores son públicas.$t$),
    ('ABOUT_US', 'en', $t$Stores: each store registers with its country, tax ID and the address it ships from, and can sell right away. We verify its payout account before paying it, and the “Verified store” badge means our team reviewed its tax details. Buyer reviews are public.$t$, $t$Stores: each store registers with the address it ships from and can sell right away. We verify its payout account before paying it. Its badges show only what we checked: “Registered seller”, “Payout verified” and “Identity verified” (identity checked with an official document or an official business registry). Buyer reviews are public.$t$),
    ('ABOUT_US', 'fr', $t$Boutiques : chaque boutique s’inscrit avec son pays, son identifiant fiscal et son adresse d’expédition, et peut vendre immédiatement. Nous vérifions son compte de versement avant de la payer, et le badge « Boutique vérifiée » indique que notre équipe a examiné ses informations fiscales. Les avis des acheteurs sont publics.$t$, $t$Boutiques : chaque boutique s’inscrit avec son adresse d’expédition et peut vendre immédiatement. Nous vérifions son compte de versement avant de la payer. Ses badges indiquent uniquement ce que nous avons vérifié : « Vendeur enregistré », « Versement vérifié » et « Identité vérifiée » (identité vérifiée avec un document officiel ou un registre officiel des entreprises). Les avis des acheteurs sont publics.$t$),
    ('ABOUT_US', 'ht', $t$Boutik: chak boutik enskri ak peyi l, idantifyan fiskal li ak adrès kote l voye pwodwi yo, epi li ka vann touswit. Nou verifye kont peman l anvan nou peye l, epi badj « Boutik verifye » vle di ekip nou an revize enfòmasyon fiskal li. Avi achtè yo piblik.$t$, $t$Boutik: chak boutik enskri ak adrès kote l voye pwodwi yo, epi li ka vann touswit. Nou verifye kont peman l anvan nou peye l. Badj li yo montre sèlman sa nou verifye: « Vandè ki anrejistre », « Peman verifye » ak « Idantite verifye » (idantite verifye ak yon dokiman ofisyèl oswa yon rejis ofisyèl antrepriz). Avi achtè yo piblik.$t$),
    ('SELLER_TERMS', 'es', $t$Datos de la tienda: declarar datos fiscales verdaderos (razón social, país e identificación fiscal) y mantenerlos al día; aparecen en los recibos de tus ventas. La insignia «Tienda verificada» se muestra cuando nuestro equipo los revisa.$t$, $t$Datos de la tienda: si declaras datos fiscales (razón social, país e identificación fiscal), deben ser verdaderos y estar al día; aparecen en los recibos de tus ventas. Declararlos no otorga ninguna insignia: «Cobro verificado» aparece cuando verificamos tu método de cobro e «Identidad verificada» cuando nuestro equipo comprueba tu identidad con un documento oficial de identidad o un registro oficial de empresas.$t$),
    ('SELLER_TERMS', 'en', $t$Store details: declare true tax details (legal name, country and tax ID) and keep them up to date; they appear on the receipts of your sales. The “Verified store” badge is shown once our team reviews them.$t$, $t$Store details: if you declare tax details (legal name, country and tax ID), they must be true and up to date; they appear on the receipts of your sales. Declaring them grants no badge: “Payout verified” appears when we verify your payout method and “Identity verified” when our team checks your identity with an official ID document or an official business registry.$t$),
    ('SELLER_TERMS', 'fr', $t$Informations de la boutique : déclarer des informations fiscales exactes (raison sociale, pays et identifiant fiscal) et les tenir à jour ; elles figurent sur les reçus de vos ventes. Le badge « Boutique vérifiée » s’affiche une fois qu’elles ont été examinées par notre équipe.$t$, $t$Informations de la boutique : si vous déclarez des informations fiscales (raison sociale, pays et identifiant fiscal), elles doivent être exactes et à jour ; elles figurent sur les reçus de vos ventes. Les déclarer n’accorde aucun badge : « Versement vérifié » apparaît lorsque nous vérifions votre moyen de versement et « Identité vérifiée » lorsque notre équipe vérifie votre identité avec une pièce d’identité officielle ou un registre officiel des entreprises.$t$),
    ('SELLER_TERMS', 'ht', $t$Enfòmasyon boutik la: deklare enfòmasyon fiskal ki vre (non legal, peyi ak idantifyan fiskal) epi kenbe yo ajou; yo parèt sou resi vant ou yo. Badj « Boutik verifye » parèt lè ekip nou an fin revize yo.$t$, $t$Enfòmasyon boutik la: si w deklare enfòmasyon fiskal (non legal, peyi ak idantifyan fiskal), yo dwe vre epi ajou; yo parèt sou resi vant ou yo. Deklare yo pa ba w okenn badj: « Peman verifye » parèt lè nou verifye metòd peman w epi « Idantite verifye » lè ekip nou an verifye idantite w ak yon dokiman idantite ofisyèl oswa yon rejis ofisyèl antrepriz.$t$);

  foreach c in array array['BUYER_PROTECTION','ABOUT_US','SELLER_TERMS'] loop
    select id, current_published_version_id into v_policy, v_cur from public.policies where code = c;
    continue when v_policy is null or v_cur is null;
    select exists (select 1 from public.policy_version_localizations l join nx_trust_repl x on x.code = c and x.locale = l.locale
                    where l.policy_version_id = v_cur and position(x.old_text in l.content->>'text') > 0) into v_changed;
    if not v_changed then
      raise notice 'NEXOVAX trust levels: % skipped (paragraph not found in the current version)', c;
      continue;
    end if;
    select coalesce(max(version_number), 0) + 1 into v_next from public.policy_versions where policy_id = v_policy;
    insert into public.policy_versions (policy_id, version_number, requires_reacceptance, created_by_user_id)
    values (v_policy, v_next, false, v_admin) returning id into v_version;
    insert into public.policy_version_localizations (policy_version_id, locale, title, content_format, content)
    select v_version, l.locale, l.title, l.content_format,
           jsonb_set(l.content, '{text}', to_jsonb(coalesce(
             (select replace(l.content->>'text', x.old_text, x.new_text) from nx_trust_repl x where x.code = c and x.locale = l.locale),
             l.content->>'text')))
      from public.policy_version_localizations l where l.policy_version_id = v_cur;
    perform public.publish_policy_version(v_version, v_admin, now());
    raise notice 'NEXOVAX trust levels: % published as version %', c, v_next;
  end loop;
end $$;
